import type { WorkflowRuntimeConfig } from "../../shared/query/runtime";
import type { WorkflowInboxResponse } from "./types";

export interface WorkflowInboxApi {
  listOpenTasks(): Promise<WorkflowInboxResponse>;
  markTaskRead(taskId: string): Promise<void>;
  retryDocument(documentId: string): Promise<void>;
}

interface ErrorEnvelope {
  error?: {
    code?: string;
    message?: string;
  };
}

export class WorkflowInboxApiError extends Error {
  status: number;
  code: string;

  constructor(
    message: string,
    status: number,
    code = "workflow_inbox_api_error",
  ) {
    super(message);
    this.name = "WorkflowInboxApiError";
    this.status = status;
    this.code = code;
  }
}

function buildUrl(baseUrl: string, path: string): string {
  return baseUrl ? `${baseUrl}${path}` : path;
}

function encodePathSegment(value: string): string {
  return encodeURIComponent(value);
}

function buildHeaders(
  headers: HeadersInit | undefined,
  hasBody: boolean,
): Headers {
  const resolved = new Headers(headers);

  if (!resolved.has("Accept")) {
    resolved.set("Accept", "application/json");
  }

  if (hasBody && !resolved.has("Content-Type")) {
    resolved.set("Content-Type", "application/json");
  }

  return resolved;
}

async function toApiError(response: Response): Promise<WorkflowInboxApiError> {
  let code = "workflow_inbox_api_error";
  let message = `Richiesta workflow fallita con stato ${response.status}.`;

  try {
    const payload = (await response.json()) as ErrorEnvelope;
    if (payload.error?.code) {
      code = payload.error.code;
    }
    if (payload.error?.message) {
      message = payload.error.message;
    }
  } catch {
    // keep default fallback message
  }

  return new WorkflowInboxApiError(message, response.status, code);
}

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    credentials: "include",
    headers: buildHeaders(init?.headers, init?.body != null),
  });

  if (!response.ok) {
    throw await toApiError(response);
  }

  if (response.status === 204) {
    return undefined as T;
  }

  return (await response.json()) as T;
}

export function createHttpWorkflowInboxApi(
  config: WorkflowRuntimeConfig,
): WorkflowInboxApi {
  return {
    listOpenTasks() {
      return requestJson<WorkflowInboxResponse>(
        buildUrl(config.apiBaseUrl, "/workflow/tasks?status=open"),
      );
    },

    async markTaskRead(taskId: string) {
      await requestJson<void>(
        buildUrl(
          config.apiBaseUrl,
          `/workflow/tasks/${encodePathSegment(taskId)}/read`,
        ),
        { method: "POST" },
      );
    },

    async retryDocument(documentId: string) {
      await requestJson<void>(
        buildUrl(
          config.apiBaseUrl,
          `/documents/${encodePathSegment(documentId)}/retry`,
        ),
        { method: "POST" },
      );
    },
  };
}
