const ORIGINAL_API_BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL;
const ORIGINAL_POLL_INTERVAL = process.env.NEXT_PUBLIC_INBOX_POLL_INTERVAL_MS;

function restoreEnv() {
  if (ORIGINAL_RUNTIME_PROFILE === undefined) {
    delete process.env.NEXT_PUBLIC_RUNTIME_PROFILE;
  } else {
    process.env.NEXT_PUBLIC_RUNTIME_PROFILE = ORIGINAL_RUNTIME_PROFILE;
  }

  if (ORIGINAL_API_BASE_URL === undefined) {
    delete process.env.NEXT_PUBLIC_API_BASE_URL;
  } else {
    process.env.NEXT_PUBLIC_API_BASE_URL = ORIGINAL_API_BASE_URL;
  }

  if (ORIGINAL_POLL_INTERVAL === undefined) {
    delete process.env.NEXT_PUBLIC_INBOX_POLL_INTERVAL_MS;
  } else {
    process.env.NEXT_PUBLIC_INBOX_POLL_INTERVAL_MS = ORIGINAL_POLL_INTERVAL;
  }
}

