describe("WorkflowInboxScreen", () => {
  it("lists open tasks, opens document detail, updates read state, and gates retry visibility", async () => {
    const validationTask = makeTask({
      id: "task-validation",
      documentId: "DOC-VAL-001",
      taskType: "validazione",
      taskStatus: "open",
      documentStatus: "da_validare",
      createdAt: "2025-01-15T10:00:00Z",
      assignedTo: "Giulia Bianchi",
      isRead: false,
      canRetry: false,
