    const retryAllowedTask = makeTask({
      id: "task-exception-allowed",
      documentId: "DOC-EX-001",
      taskType: "eccezione",
      taskStatus: "open",
      documentStatus: "eccezione",
      createdAt: "2025-01-15T10:01:00Z",
      assignedTo: null,
      isRead: false,
      canRetry: true,
    });

    const retryDeniedTask = makeTask({
      id: "task-exception-denied",
      documentId: "DOC-EX-002",
      taskType: "eccezione",
      taskStatus: "open",
      documentStatus: "eccezione",
      createdAt: "2025-01-15T10:02:00Z",
      assignedTo: "Paolo Neri",
      isRead: false,
      canRetry: false,
    });

    const api = createFakeWorkflowInboxApi([
      makeResponse([validationTask, retryAllowedTask, retryDeniedTask]),
    ]);

    const onOpenDocument = vi.fn();
    const user = userEvent.setup();

    render(
      <WorkflowInboxScreen
        api={api}
        runtimeConfig={LOCAL_RUNTIME_CONFIG}
        onOpenDocument={onOpenDocument}
      />,
    );

    const validationRow = await screen.findByTestId("task-row-task-validation");
    expect(within(validationRow).getByText("DOC-VAL-001")).toBeTruthy();
    expect(within(validationRow).getByText("Validazione")).toBeTruthy();
    expect(within(validationRow).getByText("Giulia Bianchi")).toBeTruthy();
    expect(
      within(validationRow).getByText("2025-01-15 10:00:00 UTC"),
    ).toBeTruthy();

    const openLink = within(validationRow).getByTestId("open-task-validation");
    expect(openLink.getAttribute("href")).toBe("/documents/DOC-VAL-001");

    const exceptionRow = screen.getByTestId("task-row-task-exception-allowed");
    expect(within(exceptionRow).getByText("Eccezione")).toBeTruthy();
    expect(within(exceptionRow).getByText("Non assegnato")).toBeTruthy();

    expect(screen.getByTestId("retry-task-exception-allowed")).toBeTruthy();
    expect(screen.queryByTestId("retry-task-exception-denied")).toBeNull();

    await user.click(openLink);

    await waitFor(() => {
      expect(api.markTaskRead).toHaveBeenCalledWith("task-validation");
    });

    expect(onOpenDocument).toHaveBeenCalledWith("DOC-VAL-001");
    expect(screen.getByTestId("read-state-task-validation").textContent).toBe(
      "Letto",
    );

    await user.click(screen.getByTestId("retry-task-exception-allowed"));

    await waitFor(() => {
      expect(api.retryDocument).toHaveBeenCalledWith("DOC-EX-001");
    });
  });

  it("shows the empty state when there are no open tasks", async () => {
    const api = createFakeWorkflowInboxApi([makeResponse([])]);

    render(
      <WorkflowInboxScreen api={api} runtimeConfig={LOCAL_RUNTIME_CONFIG} />,
    );

    expect(
      await screen.findByText("Nessun task aperto disponibile."),
    ).toBeTruthy();
  });

  it("shows the query error state when task loading fails", async () => {
    const api = createFakeWorkflowInboxApi({
      listOpenTasksImpl: async () => {
        throw new Error("Backend workflow non disponibile.");
      },
    });

    render(
      <WorkflowInboxScreen api={api} runtimeConfig={LOCAL_RUNTIME_CONFIG} />,
    );

    const alert = await screen.findByRole("alert");
    expect(alert.textContent).toContain("Backend workflow non disponibile.");
  });

  it("rolls back optimistic read state and still opens the document when mark-read fails", async () => {
    const unreadTask = makeTask({
      id: "task-mark-read-failure",
      documentId: "DOC-FAIL-001",
      isRead: false,
    });

    const api = createFakeWorkflowInboxApi({
      responses: [makeResponse([unreadTask]), makeResponse([unreadTask])],
      markTaskReadImpl: async () => {
        throw new Error("mark read failed");
      },
