      id: "task-retry-failure",
      documentId: "DOC-RETRY-FAIL",
      taskType: "eccezione",
      taskStatus: "open",
      documentStatus: "eccezione",
      canRetry: true,
    });

    const api = createFakeWorkflowInboxApi({
      responses: [makeResponse([retryTask]), makeResponse([retryTask])],
      retryDocumentImpl: async () => {
        throw new Error("retry failed");
      },
    });

    const user = userEvent.setup();

    render(
      <WorkflowInboxScreen api={api} runtimeConfig={LOCAL_RUNTIME_CONFIG} />,
    );

    await screen.findByText("DOC-RETRY-FAIL");
    await user.click(screen.getByTestId("retry-task-retry-failure"));

    await waitFor(() => {
      expect(api.retryDocument).toHaveBeenCalledWith("DOC-RETRY-FAIL");
    });

    expect(await screen.findByRole("alert")).toHaveTextContent(
      "Impossibile richiedere il retry del documento.",
    );
  });
});
