"use client";

import React, { useMemo, useState } from "react";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { createHttpWorkflowInboxApi, type WorkflowInboxApi } from "./api";
import {
  resolveWorkflowRuntime,
  type WorkflowRuntimeConfig,
} from "../../shared/query/runtime";
import { WorkflowStateBadge } from "../../shared/ui/stateBadge";
import { useTaskInbox } from "./useTaskInbox";
import type {
  WorkflowInboxTask,
  WorkflowTaskStatus,
  WorkflowTaskType,
} from "./types";

const taskTypeLabels: Record<WorkflowTaskType, string> = {
  validazione: "Validazione",
  eccezione: "Eccezione",
};

const taskStatusMeta: Record<
  WorkflowTaskStatus,
  { label: string; toneClasses: string }
> = {
  open: {
    label: "Aperto",
    toneClasses: "bg-slate-100 text-slate-800",
  },
  in_progress: {
    label: "In lavorazione",
    toneClasses: "bg-blue-100 text-blue-800",
  },
  completed: {
    label: "Completato",
    toneClasses: "bg-emerald-100 text-emerald-900",
  },
  cancelled: {
    label: "Annullato",
    toneClasses: "bg-zinc-100 text-zinc-700",
  },
};

export interface WorkflowInboxScreenProps {
  api?: WorkflowInboxApi;
  runtimeConfig?: WorkflowRuntimeConfig;
  onOpenDocument?: (documentId: string) => void;
}

interface WorkflowInboxPanelProps {
  api: WorkflowInboxApi;
  pollIntervalMs: number;
  onOpenDocument?: (documentId: string) => void;
}

function formatTimestamp(value: string): string {
  return value.replace("T", " ").replace("Z", " UTC");
}

export function buildWorkflowDocumentHref(documentId: string): string {
  return `/documents/${encodeURIComponent(documentId)}`;
}

function dispatchHistoryChange() {
  if (typeof window === "undefined") {
    return;
  }

  const popStateEvent =
    typeof PopStateEvent === "function"
      ? new PopStateEvent("popstate")
      : new Event("popstate");

  window.dispatchEvent(popStateEvent);
}

export function openWorkflowDocument(
  documentId: string,
  onOpenDocument?: (documentId: string) => void,
) {
  if (onOpenDocument) {
    onOpenDocument(documentId);
    return;
  }

  if (typeof window === "undefined") {
    return;
  }

  window.history.pushState({}, "", buildWorkflowDocumentHref(documentId));
  dispatchHistoryChange();
}

function canShowRetry(task: WorkflowInboxTask): boolean {
  return (
    task.taskType === "eccezione" &&
    task.taskStatus === "open" &&
    task.documentStatus === "eccezione" &&
    task.canRetry
  );
}

function TaskStatusBadge({ status }: { status: WorkflowTaskStatus }) {
  const meta = taskStatusMeta[status];

  return (
    <span
      data-task-status={status}
      className={[
        "inline-flex items-center rounded-full px-2.5 py-1 text-xs font-medium",
        meta.toneClasses,
      ].join(" ")}
    >
      {meta.label}
    </span>
  );
}

function WorkflowInboxPanel({
  api,
  pollIntervalMs,
  onOpenDocument,
}: WorkflowInboxPanelProps) {
  const {
    items,
    refreshedAt,
    isLoading,
    isFetching,
    error,
    refetch,
    markTaskRead,
    retryDocument,
    isMarkingRead,
    isRetrying,
  } = useTaskInbox(api, { pollIntervalMs });

  const [actionError, setActionError] = useState<string | null>(null);

  const handleOpen = async (task: WorkflowInboxTask) => {
    setActionError(null);

    try {
      await markTaskRead(task.id);
    } catch {
      setActionError("Impossibile aggiornare lo stato di lettura del task.");
    } finally {
      openWorkflowDocument(task.documentId, onOpenDocument);
    }
  };

  const handleRetry = async (task: WorkflowInboxTask) => {
    setActionError(null);

    try {
      await retryDocument(task.documentId);
    } catch {
      setActionError("Impossibile richiedere il retry del documento.");
    }
  };

  const queryError =
    error instanceof Error
      ? error.message
      : "Impossibile caricare la inbox task.";

  return (
    <section className="space-y-4" aria-label="Inbox workflow">
      <div className="flex items-center justify-between gap-4">
        <div>
          <h1 className="text-xl font-semibold text-slate-900">
            Inbox attività
          </h1>
          <p className="text-sm text-slate-600">
            Elenco task aperti per validazione ed eccezioni.
          </p>
        </div>

        <button
          type="button"
          onClick={() => {
            void refetch();
          }}
          className="rounded-md border border-slate-300 px-3 py-2 text-sm font-medium text-slate-700"
        >
          {isFetching ? "Aggiornamento..." : "Aggiorna elenco"}
        </button>
      </div>

      <div className="rounded-lg border border-slate-200 bg-white p-4 shadow-sm">
        <div className="flex flex-wrap items-center justify-between gap-2 text-sm text-slate-600">
          <span aria-live="polite">
            Ultimo aggiornamento:{" "}
            {refreshedAt ? formatTimestamp(refreshedAt) : "non disponibile"}
          </span>
          <span>{items.length} task</span>
        </div>

        {actionError ? (
          <div
            role="alert"
            className="mt-3 rounded-md border border-rose-200 bg-rose-50 px-3 py-2 text-sm text-rose-800"
          >
            {actionError}
          </div>
        ) : null}

        {isLoading ? (
          <div className="mt-4 rounded-md border border-slate-200 bg-slate-50 px-3 py-4 text-sm text-slate-700">
            Caricamento task in corso...
          </div>
        ) : null}

        {!isLoading && error ? (
          <div
            role="alert"
            className="mt-4 rounded-md border border-rose-200 bg-rose-50 px-3 py-4 text-sm text-rose-800"
          >
            {queryError}
          </div>
        ) : null}

        {!isLoading && !error && items.length === 0 ? (
          <div className="mt-4 rounded-md border border-slate-200 bg-slate-50 px-3 py-4 text-sm text-slate-700">
            Nessun task aperto disponibile.
          </div>
        ) : null}

        {!isLoading && !error && items.length > 0 ? (
          <div className="mt-4 overflow-x-auto">
            <table className="min-w-full border-collapse text-left text-sm">
              <caption className="sr-only">
                Elenco task aperti del workflow documentale
              </caption>
              <thead>
                <tr className="border-b border-slate-200 text-slate-600">
                  <th className="px-2 py-2 font-medium">Documento</th>
                  <th className="px-2 py-2 font-medium">Tipo task</th>
                  <th className="px-2 py-2 font-medium">Stato task</th>
                  <th className="px-2 py-2 font-medium">Stato documento</th>
                  <th className="px-2 py-2 font-medium">Creato il</th>
                  <th className="px-2 py-2 font-medium">Assegnato a</th>
                  <th className="px-2 py-2 font-medium">Lettura</th>
                  <th className="px-2 py-2 font-medium">Azioni</th>
                </tr>
              </thead>
              <tbody>
                {items.map((task) => (
                  <tr
                    key={task.id}
                    data-testid={`task-row-${task.id}`}
                    className="border-b border-slate-100 align-top"
                  >
                    <td className="px-2 py-3 font-mono text-xs text-slate-900">
                      {task.documentId}
                    </td>
                    <td className="px-2 py-3 text-slate-800">
                      {taskTypeLabels[task.taskType]}
                    </td>
                    <td className="px-2 py-3">
                      <TaskStatusBadge status={task.taskStatus} />
                    </td>
                    <td className="px-2 py-3">
                      <WorkflowStateBadge
                        state={task.documentStatus}
                        data-testid={`document-state-${task.id}`}
                      />
                    </td>
                    <td className="px-2 py-3">
                      <time dateTime={task.createdAt}>
                        {formatTimestamp(task.createdAt)}
                      </time>
                    </td>
                    <td className="px-2 py-3 text-slate-800">
                      {task.assignedTo ?? "Non assegnato"}
                    </td>
                    <td className="px-2 py-3">
                      <span
                        data-testid={`read-state-${task.id}`}
                        className={
                          task.isRead ? "text-emerald-700" : "text-amber-700"
                        }
                      >
                        {task.isRead ? "Letto" : "Non letto"}
                      </span>
                    </td>
                    <td className="px-2 py-3">
                      <div className="flex flex-wrap gap-2">
                        <a
                          href={buildWorkflowDocumentHref(task.documentId)}
                          data-testid={`open-${task.id}`}
                          onClick={(event) => {
                            event.preventDefault();
                            void handleOpen(task);
                          }}
                          aria-disabled={isMarkingRead ? "true" : "false"}
                          className="rounded-md bg-slate-900 px-3 py-2 text-xs font-medium text-white"
                        >
                          Apri dettaglio
                        </a>

                        {canShowRetry(task) ? (
                          <button
                            type="button"
                            data-testid={`retry-${task.id}`}
                            onClick={() => {
                              void handleRetry(task);
                            }}
                            disabled={isRetrying}
                            className="rounded-md border border-amber-300 px-3 py-2 text-xs font-medium text-amber-900 disabled:cursor-not-allowed disabled:opacity-60"
                          >
                            Retry
                          </button>
                        ) : null}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : null}
      </div>
    </section>
  );
}

export function WorkflowInboxScreen({
  api,
  runtimeConfig,
  onOpenDocument,
}: WorkflowInboxScreenProps) {
  const [queryClient] = useState(
    () =>
      new QueryClient({
        defaultOptions: {
          queries: {
            retry: false,
          },
          mutations: {
            retry: false,
          },
        },
      }),
  );

  const resolvedRuntime = useMemo(
    () => runtimeConfig ?? resolveWorkflowRuntime(),
    [runtimeConfig],
  );

  const resolvedApi = useMemo(
    () => api ?? createHttpWorkflowInboxApi(resolvedRuntime),
    [api, resolvedRuntime],
  );

  return (
    <QueryClientProvider client={queryClient}>
      <WorkflowInboxPanel
        api={resolvedApi}
        pollIntervalMs={resolvedRuntime.pollIntervalMs}
        onOpenDocument={onOpenDocument}
      />
    </QueryClientProvider>
  );
}

export default WorkflowInboxScreen;
