import { vi } from "vitest";
import type { WorkflowRuntimeConfig } from "../../../src/node/frontend/app/shared/query/runtime";
import type { WorkflowInboxApi } from "../../../src/node/frontend/app/workflow/inbox/api";
import type {
  WorkflowInboxResponse,
  WorkflowInboxTask,
} from "../../../src/node/frontend/app/workflow/inbox/types";

export const LOCAL_RUNTIME_CONFIG: WorkflowRuntimeConfig = {
  profile: "local",
  apiBaseUrl: "http://localhost:8000",
  pollIntervalMs: 0,
};

export function makeTask(
  overrides: Partial<WorkflowInboxTask> = {},
): WorkflowInboxTask {
  return {
    id: "task-001",
    documentId: "DOC-001",
    taskType: "validazione",
    taskStatus: "open",
    documentStatus: "da_validare",
    createdAt: "2025-01-15T10:00:00Z",
    assignedTo: "Mario Rossi",
    isRead: false,
    canRetry: false,
    ...overrides,
  };
}

export function makeResponse(
  items: WorkflowInboxTask[],
  refreshedAt = "2025-01-15T10:05:00Z",
): WorkflowInboxResponse {
  return {
    items,
    refreshedAt,
  };
}

function cloneResponse(response: WorkflowInboxResponse): WorkflowInboxResponse {
  return JSON.parse(JSON.stringify(response)) as WorkflowInboxResponse;
}

export interface FakeWorkflowInboxApiOptions {
  responses?: WorkflowInboxResponse[];
  listOpenTasksImpl?: () => Promise<WorkflowInboxResponse>;
  markTaskReadImpl?: (taskId: string) => Promise<void>;
  retryDocumentImpl?: (documentId: string) => Promise<void>;
}

export function createFakeWorkflowInboxApi(
  responsesOrOptions: WorkflowInboxResponse[] | FakeWorkflowInboxApiOptions = [],
): WorkflowInboxApi & {
  listOpenTasks: ReturnType<typeof vi.fn>;
  markTaskRead: ReturnType<typeof vi.fn>;
  retryDocument: ReturnType<typeof vi.fn>;
} {
  const options = Array.isArray(responsesOrOptions)
    ? { responses: responsesOrOptions }
    : responsesOrOptions;

  let callIndex = 0;

  const listOpenTasks = vi.fn(
    options.listOpenTasksImpl ??
      (async () => {
        const responses = options.responses ?? [];
        const response =
          responses.length > 0
            ? responses[Math.min(callIndex, responses.length - 1)]
            : makeResponse([]);

        callIndex += 1;
        return cloneResponse(response);
      }),
  );

  const markTaskRead = vi.fn(
    options.markTaskReadImpl ?? (async (_taskId: string) => undefined),
  );

  const retryDocument = vi.fn(
    options.retryDocumentImpl ?? (async (_documentId: string) => undefined),
  );

  return {
    listOpenTasks,
    markTaskRead,
    retryDocument,
  };
}
